        Assert.assertTrue("Backslashes should be escaped", result.contains("\\\\"));

        // Verify specific Unicode separator replacement logic explicitly defined in the focal method
        // \u2028 should become the literal string "\u2028"
        Assert.assertTrue("Line Separator (\\u2028) should be escaped to literal unicode sequence", 
                result.contains("\\u2028"));
        
        // \u2029 should become the literal string "\u2029"
        Assert.assertTrue("Paragraph Separator (\\u2029) should be escaped to literal unicode sequence", 
                result.contains("\\u2029"));

        // Verify that text after the last escaped character is written correctly
        Assert.assertTrue("Text ending should be preserved", result.endsWith("End"));
